def _get_remote_config_by_id(self, config_id: str) -> Optional[RemoteContentConfig]:
    """Get a remote content config by its ID."""
    if not self.content_sources:
        return None
    return next((c for c in self.content_sources if c.id == config_id), None)

def dict(self, **kwargs: Any) -> Dict[str, Any]:
    """
    Override the default dict method to `exclude_unset` by default. This function patches
    `exclude_unset` to work include fields within non-None default values.
    """
    # Note: the logic here is multiplexed given the levers exposed in Pydantic V1 vs V2
    # Pydantic V1's .dict can be extremely slow, so we do not want to call it twice.
    #
    # We'd ideally do the same for Pydantic V2, but it shells out to a library to serialize models
    # that we have less control over, and this is less intrusive than custom serializers for now.
    if IS_PYDANTIC_V2:
        kwargs_with_defaults_exclude_unset = {
            **kwargs,
            "by_alias": True,
            "exclude_unset": True,
            "exclude_none": False,
        }
        kwargs_with_defaults_exclude_none = {
            **kwargs,
            "by_alias": True,
            "exclude_none": True,
            "exclude_unset": False,
        }
        dict_dump = deep_union_pydantic_dicts(
            super().model_dump(**kwargs_with_defaults_exclude_unset),  # type: ignore[misc]
            super().model_dump(**kwargs_with_defaults_exclude_none),  # type: ignore[misc]
        )

    else:
        _fields_set = self.__fields_set__.copy()

        fields = _get_model_fields(self.__class__)
        for name, field in fields.items():
            if name not in _fields_set:
                default = _get_field_default(field)

                # If the default values are non-null act like they've been set
                # This effectively allows exclude_unset to work like exclude_none where
                # the latter passes through intentionally set none values.
                if default is not None or ("exclude_unset" in kwargs and not kwargs["exclude_unset"]):
                    _fields_set.add(name)

                    if default is not None:
                        self.__fields_set__.add(name)

        kwargs_with_defaults_exclude_unset_include_fields = {
            "by_alias": True,
            "exclude_unset": True,
            "include": _fields_set,
            **kwargs,
        }

        dict_dump = super().dict(**kwargs_with_defaults_exclude_unset_include_fields)

    return cast(
        Dict[str, Any],
        convert_and_respect_annotation_metadata(object_=dict_dump, annotation=self.__class__, direction="write"),
    )

def __hash__(self):
    """Returns a hash computed using the shape descriptor's hash implementation."""
    # NOTE: The name-uid-based hash implementation is called if no shape is defined
    if self.shape is None:
        return super().__hash__()
    # Otherwise, use the shape's hash implementation
    return self.shape.__hash__()

def dofs_axes(self) -> Vector[Any, Int]:
    """
    Returns the indices of the joint's DoF axes.
    """
    if self.value == self.FREE:
        return wp.constant(vec6i(0, 1, 2, 3, 4, 5))
    if self.value == self.REVOLUTE:
        return wp.constant(vec1i(3))
    elif self.value == self.PRISMATIC:
        return wp.constant(vec1i(0))
    elif self.value == self.CYLINDRICAL:
        return wp.constant(vec2i(0, 3))
    elif self.value == self.UNIVERSAL:
        return wp.constant(vec2i(3, 4))
    elif self.value == self.SPHERICAL:
        return wp.constant(vec3i(3, 4, 5))
    elif self.value == self.GIMBAL:
        return wp.constant(vec3i(3, 4, 5))
    elif self.value == self.CARTESIAN:
        return wp.constant(vec3i(0, 1, 2))
    elif self.value == self.FIXED:
        return []  # Empty vector (TODO: wp.constant(vec0i()))
    else:
        raise ValueError(f"Unknown joint DoF type: {self.value}")

def compile_prompt_pattern(pattern):
    r"""Compile a prompt pattern with line-start anchoring to prevent false matches.

    Prepends ``(?:^|\r?\n)`` to the pattern so that prompts only match at the
    start of a line (beginning of buffer or after a newline).  Already-compiled
    ``re.Pattern`` objects and patterns that already start with a line anchor
    (``^``, ``\r``, ``\n``) are returned unchanged.

    :param pattern:
        A prompt regex string or compiled ``re.Pattern``.

    :returns:
        A compiled ``re.Pattern`` with ``re.MULTILINE`` enabled.
    """
    if isinstance(pattern, re.Pattern):
        return pattern
    if pattern.startswith(("^", r"\r", r"\n")):
        return re.compile(pattern, re.MULTILINE)
    return re.compile(r"(?:^|\r?\n)" + pattern, re.MULTILINE)

def _retry_timeout(response: httpx.Response, retries: int) -> float:
    """
    Determine the amount of time to wait before retrying a request.
    This function begins by trying to parse a retry-after header from the response, and then proceeds to use exponential backoff
    with a jitter to determine the number of seconds to wait.
    """

    # 1. Check Retry-After header first
    retry_after = _parse_retry_after(response.headers)
    if retry_after is not None and retry_after > 0:
        return min(retry_after, MAX_RETRY_DELAY_SECONDS)

    # 2. Check X-RateLimit-Reset header (with positive jitter)
    ratelimit_reset = _parse_x_ratelimit_reset(response.headers)
    if ratelimit_reset is not None:
        return _add_positive_jitter(min(ratelimit_reset, MAX_RETRY_DELAY_SECONDS))

    # 3. Fall back to exponential backoff (with symmetric jitter)
    backoff = min(INITIAL_RETRY_DELAY_SECONDS * pow(2.0, retries), MAX_RETRY_DELAY_SECONDS)
    return _add_symmetric_jitter(backoff)

def test_dataset_names_filter(self, tmp_path):
    """Only selected datasets are loaded when dataset_names is specified."""
    for name in ("a.jsonl", "b.jsonl"):
        (tmp_path / name).write_text(
            json.dumps({
                "messages": [
                    {"role": "user", "content": f"From {name}"},
                    {"role": "assistant", "content": "Ok"},
                ],
            }) + "\n",
        )

    meta_file = tmp_path / "meta.json"
    meta_file.write_text(json.dumps({
        "dataset_a": {"file_name": "a.jsonl"},
        "dataset_b": {"file_name": "b.jsonl"},
    }))

    result = ds.make_meta_dataset(str(meta_file), dataset_names=["dataset_a"])
    assert len(result) == 1
    assert result[0]["conversation"][0]["content"][0]["text"] == "From a.jsonl"

def _boundary_values(boundaries, min_val, max_val, step=1, width=5, sparse_count=100):
  """Generate test values dense around boundaries and sparse across the full range.

  For threshold-style safety checks, exhaustively testing every value is wasteful.
  This generates values ±width*step around each boundary, plus sparse sampling."""
  values = set()
  for b in boundaries:
    for offset in range(-width, width + 1):
      v = round(b + offset * step, 2)
      if min_val <= v < max_val:
        values.add(v)
  sparse_step = max(step, (max_val - min_val) / sparse_count)
  for v in np.arange(min_val, max_val, sparse_step):
    values.add(round(v, 2))
  return sorted(values)

def should_exclude_file(file_path: str) -> bool:
    """Exclude auto-generated (protobuf, lock files) and large files (notebooks)."""
    path = Path(file_path)

    if path.suffix in {".py", ".pyi"} and path.is_relative_to("mlflow/protos"):
        return True

    if path.name in {"uv.lock", "yarn.lock", "package-lock.json"}:
        return True

    if path.suffix == ".java" and path.exists():
        with path.open() as f:
            first_line = f.readline()
        if "Generated by the protocol buffer compiler" in first_line:
            return True

    if path.suffix == ".ipynb":
        return True

    return False

def grep_count_files(name: str, file_list: list[str], *,
                     word_boundary: bool = True) -> list[str]:
    """Return list of files containing name. Replacement for ``grep -rl -w name``."""
    if word_boundary:
        pat = re.compile(r"\b" + re.escape(name) + r"\b")
    else:
        pat = re.compile(re.escape(name))
    matching: list[str] = []
    for filepath in file_list:
        abs_path = filepath if os.path.isabs(filepath) else str(PROJECT_ROOT / filepath)
        content = _read_file_text(abs_path)
        if content is None:
            continue
        if pat.search(content):
            matching.append(filepath)
    return matching
